{
  "task_category": "public_documentation_generation_fr",
  "doc_path": "docs/TASK_CATALOG_FR.md",
  "summary_fr": "Catalogue des taches deleguables a Mistral via le skill `mistral-subagent` dans ce depot, avec routage par modele et bonnes pratiques operationnelles pour les projets reels.",
  "content": {
    "title": "Catalogue des taches deleguables a Mistral - Documentation FR",
    "objectif": "Ce document recense les taches concretes et validees dans ce depot pour lesquelles le modele Mistral (ou ses variantes) est adapte, avec des exemples de routage par modele et des workflows operationnels pour les projets reels. Il complete le README et le quickstart FR existants en fournissant une reference technique et pratique pour les operateurs et developpeurs.",
    "quand_deleguer_a_mistral": [
      {
        "critere": "Taches textuelles ou structurees necessitant une analyse, une generation ou une transformation precise.",
        "exemples": [
          "Extraction JSON stricte a partir de briefs ou de documents techniques.",
          "Critique et reecriture de copies UI/UX (ex: messages, labels, micro-copy).",
          "Traduction structuree de notes ou de documentation publique.",
          "Triage strict de commentaires de review (ex: GitHub, GitLab).",
          "Planification de workflows RAG/embeddings multi-projets.",
          "Generation ou amelioration de templates GitHub (issues, PRs)."
        ],
        "exclusions": [
          "Taches necessitant une interaction directe avec des systemes externes (APIs, bases de donnees) sans validation intermediaire.",
          "Modifications de code critiques sans revue humaine.",
          "Generation de contenu non verifiable ou subjectif (ex: design visuel, choix artistiques)."
        ]
      },
      {
        "critere": "Taches necessitant une analyse de texte ou de code avec un retour structure.",
        "exemples": [
          "Revue de diff simple avec findings au format JSON.",
          "Audit borne de depot public avec suggestions documentaires.",
          "Idees de tests unitaires bornes pour des composants specifiques."
        ]
      },
      {
        "critere": "Taches de transcription ou d'extraction de donnees non structurees.",
        "exemples": [
          "OCR et extraction structuree de documents (PDF, images).",
          "Transcription audio FR bornee (ex: reunions, interviews)."
        ]
      }
    ],
    "routage_par_modele": {
      "mistral-small-latest": {
        "cas_usage": [
          "Taches textuelles simples necessitant une reponse rapide et concise.",
          "Extraction de donnees structurees (JSON) a partir de texte brut.",
          "Traduction ou reformulation de phrases courtes.",
          "Triage de commentaires de review (ex: GitHub) avec classification basique."
        ],
        "limites": [
          "Peu adapte pour des analyses complexes ou des taches necessitant une comprehension contextuelle profonde.",
          "Risque d'erreurs sur des donnees techniques specialisees."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Extraire les points cles de ce brief en JSON\" --context-file brief.md --model mistral-small-latest"
      },
      "mistral-medium-latest": {
        "cas_usage": [
          "Analyse de texte ou de code avec un niveau de detail intermediaire.",
          "Generation de templates ou de structures documentaires (ex: issues GitHub).",
          "Revue de diff avec findings detailles mais non critiques.",
          "Planification de workflows RAG/embeddings pour des projets simples."
        ],
        "limites": [
          "Moins performant que `mistral-large-latest` pour des taches complexes ou multi-etapes.",
          "Necessite une validation humaine pour les decisions techniques."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Generer une issue GitHub pour corriger ce bug\" --context-file code_diff.md --model mistral-medium-latest"
      },
      "mistral-large-latest": {
        "cas_usage": [
          "Taches complexes necessitant une comprehension approfondie du contexte.",
          "Audit borne de depot public avec suggestions documentaires detaillees.",
          "Critique et reecriture de copies UI/UX pour des experiences scroll-driven.",
          "Planification de workflows RAG/embeddings multi-projets.",
          "Transcription audio FR bornee avec structuration des donnees."
        ],
        "limites": [
          "Cout et latence plus eleves que les autres modeles.",
          "A reserver aux taches critiques ou necessitant une haute precision."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Planifier un workflow RAG pour le projet AI_VIDEO_WEBGL_COMPETENCES\" --context-file project_structure.json --model mistral-large-latest"
      },
      "devstral-latest": {
        "cas_usage": [
          "Generation ou amelioration de code (ex: scripts, fonctions).",
          "Revue de code avec suggestions de corrections ou d'optimisations."
        ],
        "limites": [
          "Specialise pour le code : moins adapte pour des taches textuelles pures.",
          "Necessite un contexte technique precis pour eviter les erreurs."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Corriger ce script Node.js pour gerer les erreurs de maniere asynchrone\" --context-file script.js --model devstral-latest"
      },
      "codestral-latest": {
        "cas_usage": [
          "Taches de developpement avance (ex: refactoring, implementation de features).",
          "Generation de code a partir de specifications detaillees."
        ],
        "limites": [
          "Cout eleve : a utiliser pour des taches critiques uniquement.",
          "Necessite une validation humaine approfondie."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Implementer une fonction de parsing JSON securisee pour ce projet\" --context-file requirements.txt --model codestral-latest"
      },
      "mistral-ocr-latest": {
        "cas_usage": [
          "Extraction de texte a partir d'images ou de PDFs.",
          "OCR pour des documents structures (ex: factures, formulaires)."
        ],
        "limites": [
          "Qualite variable selon la qualite de l'image source.",
          "Necessite une post-validation pour les donnees critiques."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Extraire le texte de ce PDF et le structurer en JSON\" --context-file document.pdf --model mistral-ocr-latest"
      },
      "mistral-embed": {
        "cas_usage": [
          "Generation d'embeddings pour des projets RAG ou de recherche semantique.",
          "Indexation de documents pour des workflows de type recherche vectorielle."
        ],
        "limites": [
          "Necessite un contexte technique pour l'integration avec des outils d'embedding.",
          "Cout calculatoire a prendre en compte pour les gros volumes."
        ],
        "exemple_commande": "node mistral-subagent/scripts/mistral-subagent.mjs run --task \"Generer des embeddings pour les fichiers Markdown de ce projet\" --context-file project_files/ --model mistral-embed"
      },
      "mistral-moderation-latest": {
        "cas_usage": [
          "Moderation de contenu (ex: detection de propos toxiques, spam).",
          "Filtrage pre-vol de commentaires ou de contributions avant delegation."
        ],
